Script:
ComponentManagement = {
	init: async function (app, container) {
		app = app || session.app;
		container = container || $(".component[name=ComponentManagement]");
		api.addToMetaCache([
			{
        "Name": "ContentManagement",
        "Types": [
            [meta[ContentManagement/Component]]
        ]
    }
		]);
		var config = {
			endpoint: "ContentManagement/Component",
			odataAppend: "?$filter=AppId eq " + app.Id,
			group: {
				field: "Key"
			},
			sort: [
				{
					field: "Key", dir: "asc"
				},
				{
					field: "Name", dir: "asc"
				}
			]
		};
		let ds = await model.getDatasource(config);
		var grid = new GridWidget(container, ds);
        grid.toolbar = [
        {
            template: "<div class='btn-group btn-group-sm'> \
                <button class='btn btn-primary' name='create'> \
                    <span class='k-icon k-i-plus'></span>[resource_displayname[new]] \
                </button> \
                <button class='btn btn-primary' name='migrate'> \
                    <span class='k-icon k-i-arrow-up'></span>[resource_displayname[migrate]] \
                </button> \
            </div>"
        }];
		grid.search = {
			fields: ["Key", "ResourceKey", "Name", "LastUpdatedBy"]
		};
		grid.columns = [
			{
				field: "Key",
				title: "[resource_displayname[key]]"
			},
			{
				field: "ResourceKey",
				title: "[resource_displayname[resourcekey]]"
			},
			{
				field: "Name",
				title: "[resource_displayname[name]]"
			},
			{
				field: "LastUpdated",
				title: "[resource_displayname[lastupdated]]",
				type: "date",
				format: "{0:g}"
			},
            {
				field: "LastUpdatedBy",
				title: "[resource_displayname[lastupdatedby]]"
			},
		];
		grid.commands.push({
			name: "save",
			icon: "k-i-save",
			text: "[resource_displayname[save]]"
		});
		grid.commands.push({
			name: "delete",
			icon: "k-i-trash",
			text: "[resource_displayname[delete]]"
		});
		grid.detailTemplate = kendo.template($("[name=componentDetails]", container).html()),
		grid.groupable = false;
		grid.searchable = true;
		grid.filterable = true;
		grid.detailExpand = function (e) {
			$(e.detailRow).find(".monaco-editor").css("visibility", "visible");
			var component = this.dataItem(e.masterRow);
			var editorContainer = $("[name=componentEditor]", e.detailRow);
			["content", "script"].forEach((name) => {
				var tabId = `component-${name}-tab-${component.Id}`;
				var paneId = `component-${name}-${component.Id}`;
				$(`[data-editor-tab=${name}]`, editorContainer).attr({
					id: tabId,
					"data-bs-target": `#${paneId}`,
					"aria-controls": paneId
				});
				$(`[data-editor-pane=${name}]`, editorContainer).attr({
					id: paneId,
					"aria-labelledby": tabId
				});
			});
			if ($(e.detailRow).find(".monaco-editor").length === 0) {
				var contentEditor = $(e.detailRow).find("div[name=content]");
				var scriptEditor = $(e.detailRow).find("div[name=script]");
				var html = new HTMLMonacoEditor(contentEditor[0], {
					code: component.Content
				});
				var script = new JavaScriptMonacoEditor(scriptEditor[0], {
					code: component.Script
				});
				html.onChange = (e) => {
					component.Content = html.getValue();
				}; 
				script.onChange = (e) => {
					component.Script = script.getValue();
				};
				var resizeEditors = () => {
					html.editor?.layout();
					script.editor?.layout();
				};
				html.init();
				script.init();
				$("[data-bs-toggle=tab]", editorContainer).on("shown.bs.tab", resizeEditors);
				resizeEditors();
			}
		};
		grid.detailCollapse = function (e) {
			$(e.detailRow).find(".monaco-editor").css("visibility", "hidden");
		};
		grid.dataBound = function () {
			$("button[name=save]", grid.gridElement).on("click", (e) => ComponentManagement.save(e, grid));
			$("button[name=delete]", grid.gridElement).on("click", (e) => ComponentManagement.destroy(e, grid));
		};
		await grid.init();
		$("button[name=create]", grid.gridElement).on("click", (e) => ComponentManagement.newComponent(e, grid, app));
		$("button[name=migrate]", grid.gridElement).off("click").on("click", (e) => ComponentManagement.migrate(e, app));
	},

	migrate: function (e, app) {
		e.preventDefault();
		var d = new Dialog({
			width: Math.min(1100, window.innerWidth - 40),
			height: Math.min(520, window.innerHeight - 80),
			title: "[resource_displayname[migrateComponents]]"
		});
		d.template = $("[name=componentMigrationComponent]").first().html();
		d.init(() => ComponentMigration.init(app, $(".component[name=ComponentMigration]", d.element)));
	},

  newComponent: async function (e, grid, app) {
      e.preventDefault();

      var createComponentDialog = new Dialog({
          width: Math.min(600, window.innerWidth - 40),
          height: "auto",
          title: "[resource_displayname[CreateNewComponent]]"
      });

      createComponentDialog.template =
          $("script[name=\"newComponentDialog\"]")
              .first()
              .html();

      createComponentDialog.events.create = async function (e) {
          e.preventDefault();

          var component = {
              Id: 0,
              AppId: app.Id,
              Name: $("input[name=\"name\"]", createComponentDialog.element).val(),
              Key: $("input[name=\"key\"]", createComponentDialog.element).val(),
              ResourceKey: $("input[name=\"resourceKey\"]", createComponentDialog.element).val(),
              Content: "",
              Script: ""
          };

          await api.add("ContentManagement/Component", component)
              .then(function () {
                  notification.success(
                      "[resource_displayname[componentcreated]]"
                  );

                  grid.refresh();
                  createComponentDialog.events.close();
              })
              .catch(function (err) {
                  error(err);
              });
      };

      await createComponentDialog.init();
  },

	delay: function (callback, ms) {
		var timer = 0;
		return function () {
			var context = this, args = arguments;
			clearTimeout(timer);
			timer = setTimeout(function () {
				callback.apply(context, args);
			}, ms || 0);
		};
	},

	save: async function (e, grid) {
		e.preventDefault();
		var component = grid.dataItem($(e.currentTarget).closest("tr"));
		await component.save(e);
		notification.success("Component Saved");
	},

	destroy: async function (e, grid) {
		e.preventDefault();
		var d = new ConfirmDialog({
			title: "[resource_displayname[areyousure]]",
			question: "[resource_displayname[areyousure]]",
			confirm: "[resource_displayname[confirm]]",
			close: "[resource_displayname[close]]"
		});
		d.events.confirm = async function () {
			var component = grid.dataItem($(e.currentTarget).closest("tr"));
			await component.destroy(e);
			notification.success("[resource_displayname[deleted]]");
			grid.refresh();
			d.events.close();
		};
		d.init();
	}
};
